{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text for accessibility.",
      "required": true
    },
    {
      "name": "options",
      "type": "MultiSelectorOptionType[]",
      "description": "Array of items: strings, objects with value/label/icon/disabled, dividers, or sections. An option may carry `action`: one node — an IconButton, a Button, a menu trigger — the caller renders and names. Once any option does, the popup is a grid whose rows pair the option with its action: Up/Down move rows, the inline-end arrow reaches the action, Enter fires it, pointer and touch press it directly, and pressing it never changes the selection.",
      "required": true
    },
    {
      "name": "value",
      "type": "string[]",
      "description": "Currently selected values.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: string[], change?: MultiSelectorChange) => void",
      "description": "Called when the selection changes. A creation (hasCreate) arrives with `{type: \"create\", query}` as the second argument and the query appended to value; the caller adds the matching option in that same update. Every other change passes no descriptor, so a one-argument handler keeps working.",
      "required": true
    },
    {
      "name": "changeAction",
      "type": "(value: string[]) => void | Promise<void>",
      "description": "Async action on change. Fires after onChange."
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown when no value is selected.",
      "default": "'Select...'"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size variant for the selector.",
      "default": "'md'"
    },
    {
      "name": "variant",
      "type": "'input' | 'secondary' | 'ghost'",
      "description": "Visual trigger style. input is the bordered input treatment for forms; secondary matches the secondary buttons of the active theme (borderless and neutral-filled by default) for navs and toolbars; ghost is borderless and transparent, matching ghost buttons for toolbar usage.",
      "default": "'input'"
    },
    {
      "name": "triggerDisplay",
      "type": "'count' | 'labels' | 'badges'",
      "description": "How to display selected items in the trigger.",
      "default": "'count'"
    },
    {
      "name": "formatValue",
      "type": "(items: {value: string; label: string}[]) => string",
      "description": "Formats the trigger text when triggerDisplay=\"count\" or \"labels\". Receives the selected items (value plus resolved label); the count is items.length. Not used by triggerDisplay=\"badges\"."
    },
    {
      "name": "maxBadges",
      "type": "number",
      "description": "Maximum badges to show before \"+N\". Only for triggerDisplay=\"badges\".",
      "default": "3"
    },
    {
      "name": "hasSelectAll",
      "type": "boolean",
      "description": "Whether to show a select-all checkbox."
    },
    {
      "name": "selectAllLabel",
      "type": "string",
      "description": "Label for the select-all checkbox.",
      "default": "'Select all'"
    },
    {
      "name": "hasSearch",
      "type": "boolean",
      "description": "Whether to show a search input for filtering options. As the user types, the match count (or \"No results found\") is announced to screen readers via a polite live region. The search field has built-in affordances: a leading magnifier icon and, once a query is typed, a trailing clear (✕) button that resets the query and returns focus to the input."
    },
    {
      "name": "searchPlaceholder",
      "type": "string",
      "description": "Placeholder text for the search input.",
      "default": "'Search...'"
    },
    {
      "name": "emptyText",
      "type": "ReactNode",
      "description": "Content shown in the dropdown panel when there are no options to show, and announced in a polite live region when the panel opens. The announcement is the text this content renders, read from the DOM, so an element is announced as written and aria-hidden parts are left out of both. Not shown while isLoading.",
      "default": "'No options'"
    },
    {
      "name": "emptySearchText",
      "type": "ReactNode",
      "description": "Content shown in the dropdown panel when a search query matches no options, and announced in a polite live region at the same time. The announcement is the text this content renders, read from the DOM, so an element is announced as written and aria-hidden parts are left out of both.",
      "default": "'No results found'"
    },
    {
      "name": "hasCreate",
      "type": "boolean",
      "description": "With hasSearch, offers a `Create \"<query>\"` row first in the list when the typed text equals no option label under the search’s case-insensitive matching. Picking it, or Enter with nothing highlighted, calls onChange with the query appended to value and a `{type: \"create\", query}` descriptor, then clears the search; the caller must add an option for the new value in that update. Nothing is offered while isLoading. Without hasSearch it warns in development and offers nothing.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the selector."
    },
    {
      "name": "isReadOnly",
      "type": "boolean",
      "description": "Makes the selector read-only: the selected values stay visible, focusable, and included in form submission, and retain their combobox identity with aria-readonly. The selection surface, clear action, and disclosure indicator are removed. Unlike isDisabled, the control is not dimmed. isDisabled takes precedence when both are set.",
      "default": "false"
    },
    {
      "name": "htmlName",
      "type": "string",
      "description": "The HTML name attribute for form submissions. Renders one hidden input per selected value, like a native multi-select."
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the selector is disabled. With isDisabled, shows the reason as a tooltip on hover and keyboard focus of the trigger, which stays focusable (aria-disabled) like every disabled selector; activation stays blocked. Use this instead of wrapping a disabled MultiSelector in Tooltip."
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the label while keeping it accessible."
    },
    {
      "name": "description",
      "type": "string",
      "description": "Helper text displayed below the label."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Marks the field as optional."
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Marks the field as required."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Shows a loading spinner in the trigger."
    },
    {
      "name": "status",
      "type": "{type: 'error' | 'warning' | 'success', message?: string}",
      "description": "Validation status with an optional message."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the bordered input and is only valid for the input variant; secondary and ghost selectors detach attached status messages by default. Use tooltip for compact toolbar controls.",
      "default": "'attached' for input selectors; 'detached' for secondary and ghost selectors"
    },
    {
      "name": "renderOption",
      "type": "(option: MultiSelectorOptionData) => ReactNode",
      "description": "Custom render function for each selectable option in the dropdown. Not called for dividers, sections, or the select-all row."
    },
    {
      "name": "indicatorPosition",
      "type": "'start' | 'end'",
      "description": "Which edge of the option row carries the checkbox. end pushes it to the far edge of the row, including on the select-all row.",
      "default": "'start'"
    },
    {
      "name": "presentation",
      "type": "'popover' | 'bottom-sheet' | 'adaptive'",
      "description": "How the option list is presented. adaptive uses a bottom sheet on compact touch screens and an anchored popover otherwise.",
      "default": "'popover'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "startIcon",
      "type": "IconType | ReactNode",
      "description": "Icon displayed at the start of the selector trigger."
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows a clear button when values are selected.",
      "default": "false"
    },
    {
      "name": "isDefaultOpen",
      "type": "boolean",
      "description": "Whether the dropdown starts open on mount.",
      "default": "false"
    },
    {
      "name": "renderTrigger",
      "type": "(props: MultiSelectorRenderTriggerProps) => ReactNode",
      "description": "Render the control the panel hangs off — a glyph in a list row, a chip, an icon button — instead of the selector's own field and button. Spread the given props ({ref, id, onClick, onKeyDown, onFocus, aria-haspopup, aria-expanded, aria-controls, aria-busy}) onto it; the listbox is anchored to that control and named by `label`. The field chrome (Field, status, clear, spinner) is not rendered. Pair with handleRef to open from a keystroke elsewhere."
    },
    {
      "name": "handleRef",
      "type": "React.Ref<MultiSelectorHandle>",
      "description": "Imperative handle with open(), close(), toggle() and isOpen(). Prefer it over mirroring open state in the parent; the selector owns its visibility."
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Called whenever the panel opens or closes, however it happened: the trigger, the keyboard, a light dismiss, Escape, or the handle."
    },
    {
      "name": "onClick",
      "type": "(event: MouseEvent) => void",
      "description": "Click handler on the trigger (or the renderTrigger control). Runs after the built-in toggle and cannot cancel it."
    },
    {
      "name": "onFocus",
      "type": "(event: FocusEvent) => void",
      "description": "Focus handler on the trigger. Runs before the selector's own focus handling."
    },
    {
      "name": "onKeyDown",
      "type": "(event: KeyboardEvent) => void",
      "description": "Key handler on the trigger button. Runs after the built-in keyboard model and is skipped for keys it handles and cancels."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds the value, icons, and end controls. Never the trigger button itself."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
